-- =============================================================================
-- NFS-e: lista nacional de serviços e cadastro dos serviços pelos CNAEs
--
-- A nota nacional leva o código de tributação nacional (item, subitem e
-- desdobro da LC 116/2003), não o CNAE. Esta migração guarda a lista oficial
-- (Anexo B do leiaute v1.01, de 22/01/2026: 338 códigos) para o escritório
-- escolher o serviço pelo nome, conferir o código ao salvar e anotar de qual
-- atividade (CNAE) da empresa ele veio.
-- =============================================================================

create table public.nfse_lista_servicos (
  codigo text primary key check (codigo ~ '^[0-9]{6}$'),
  item smallint not null check (item between 1 and 99),
  subitem smallint not null check (subitem between 1 and 99),
  desdobro smallint not null check (desdobro between 1 and 99),
  descricao text not null,
  descricao_subitem text,
  descricao_item text,
  check (codigo = lpad(item::text, 2, '0') || lpad(subitem::text, 2, '0') || lpad(desdobro::text, 2, '0'))
);
comment on table public.nfse_lista_servicos is
  'Lista nacional de serviços da NFS-e (Anexo B, leiaute v1.01 de 22/01/2026): códigos de tributação nacional.';

alter table public.nfse_lista_servicos enable row level security;
create policy nfse_lista_servicos_leitura on public.nfse_lista_servicos for select to authenticated using (true);
revoke all on public.nfse_lista_servicos from anon, authenticated;
grant select on public.nfse_lista_servicos to authenticated;


-- De qual atividade (CNAE) da empresa o serviço veio (só para referência: a nota não leva o CNAE)
alter table public.nfse_servicos
  add column cnae text check (cnae is null or cnae ~ '^[0-9]{4}-[0-9]/[0-9]{2}$');

create or replace function public.nfse_servico_salvar(p_empresa_id uuid, p_id uuid, p_dados jsonb)
returns uuid
language plpgsql
security definer
set search_path = ''
as $$
declare
  v_id uuid;
  v_codigo text := p_dados ->> 'codigo_tributacao_nacional';
begin
  perform app.exigir(p_empresa_id, 'nfse.configurar');
  if not exists (select 1 from public.nfse_lista_servicos where codigo = v_codigo) then
    raise exception 'O código % não está na lista nacional de serviços. Escolha o serviço pela busca.', coalesce(v_codigo, '(vazio)')
      using errcode = '22023';
  end if;
  if p_id is null then
    values (p_empresa_id, trim(p_dados ->> 'nome'), v_codigo,
            nullif(p_dados ->> 'codigo_tributacao_municipal', ''), nullif(p_dados ->> 'codigo_nbs', ''),
            nullif(trim(p_dados ->> 'descricao_padrao'), ''), coalesce((p_dados ->> 'ativo')::boolean, true),
            nullif(p_dados ->> 'cnae', ''))
    returning id into v_id;
  else
    update public.nfse_servicos
       set nome = trim(p_dados ->> 'nome'),
           codigo_tributacao_nacional = v_codigo,
           codigo_tributacao_municipal = nullif(p_dados ->> 'codigo_tributacao_municipal', ''),
           codigo_nbs = nullif(p_dados ->> 'codigo_nbs', ''),
           descricao_padrao = nullif(trim(p_dados ->> 'descricao_padrao'), ''),
           ativo = coalesce((p_dados ->> 'ativo')::boolean, true),
           cnae = nullif(p_dados ->> 'cnae', '')
     where id = p_id and empresa_id = p_empresa_id
    returning id into v_id;
    if v_id is null then
      raise exception 'Serviço não encontrado.';
    end if;
  end if;
  return v_id;
end;
$$;
